#include <array>
#include <iostream>
#include <string>
#include <vector>

int main() {
    int crudo[3] = {1, 2, 3};         // tamano fijo, sin size()
    std::array<int, 3> fijo{4, 5, 6}; // fijo, pero con .size()
    std::vector<int> dinamico{7, 8};  // crece en ejecucion
    std::string texto = "hola";       // secuencia de char

    dinamico.push_back(9);

    std::cout << crudo[0] << '\n';         // 1
    std::cout << fijo.size() << '\n';      // 3
    std::cout << dinamico.size() << '\n';  // 3
    std::cout << texto.size() << '\n';     // 4
    std::cout << texto + " mundo" << '\n'; // hola mundo
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v{10, 20, 30};
    v.push_back(40);

    std::cout << v.size() << '\n';                       // 4
    std::cout << v.front() << ' ' << v.back() << '\n';   // 10 40
    std::cout << v.at(2) << '\n';                        // 30
    std::cout << (v.capacity() >= v.size()) << '\n';     // 1

    for (int x : v) {
        std::cout << x << ' ';
    }
    std::cout << '\n';                                   // 10 20 30 40
    return 0;
}

#include <iostream>
#include <vector>

double media(const std::vector<double>& datos) {
    if (datos.empty()) {
        return 0.0;
    }
    double suma = 0.0;
    for (double x : datos) {
        suma += x;
    }
    return suma / static_cast<double>(datos.size());
}

int main() {
    std::vector<double> datos;
    datos.reserve(5);   // una sola reserva para cinco elementos

    for (int i = 1; i <= 5; ++i) {
        datos.push_back(i * 1.5);
    }

    std::cout << datos.size() << '\n';              // 5
    std::cout << (datos.capacity() >= 5) << '\n';   // 1
    std::cout << media(datos) << '\n';              // 4.5
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> palabras{"vector", "de", "cadenas", "en", "cpp"};

    std::size_t total = 0;
    std::string larga;

    for (const std::string& p : palabras) {
        total += p.size();
        if (p.size() > larga.size()) {
            larga = p;
        }
    }

    std::cout << palabras.size() << '\n'; // 5
    std::cout << total << '\n';           // 20
    std::cout << larga << '\n';           // cadenas
    return 0;
}

