#include <iostream>
#include <vector>

int main() {
    std::vector<int> notas{7, 4, 9, 6, 10};

    int minimo = notas.front();
    int maximo = notas.front();
    double suma = 0.0;

    for (int n : notas) {
        if (n < minimo) minimo = n;
        if (n > maximo) maximo = n;
        suma += n;
    }

    std::cout << minimo << ' ' << maximo << ' '
              << suma / static_cast<double>(notas.size()) << '\n'; // 4 10 7.2
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> palabras{"uno", "computadora", "de", "algoritmo", "ia"};

    int largas = 0;
    std::string mayor;

    for (const std::string& p : palabras) {
        if (p.size() > 4) ++largas;
        if (p.size() > mayor.size()) mayor = p;
    }

    std::cout << largas << '\n';  // 2
    std::cout << mayor << '\n';   // computadora
    return 0;
}
